import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Scale-Missing-Values.md","filePath":"manual-zh/CTABLES-Scale-Missing-Values.md","lastUpdated":1785684581000}'),S={name:"manual-zh/CTABLES-Scale-Missing-Values.md"};function o(h,t,c,n,I,l){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-9-3-标度缺失值" tabindex="-1">15.7.9.3 标度缺失值 <a class="header-anchor" href="#_15-7-9-3-标度缺失值" aria-label="Permalink to &quot;15.7.9.3 标度缺失值&quot;">​</a></h4><pre><code>/SMISSING {VARIABLE _|_ LISTWISE}
</code></pre><p><code>SMISSING</code> 子命令必须位于第一个 <code>TABLE</code> 子命令之前，用于控制生成所有输出表时对标度变量缺失值的处理方式。<code>SMISSING</code> 是可选的。</p><p>使用默认的 <code>SMISSING=VARIABLE</code> 时，缺失值按变量逐个排除。使用 <code>SMISSING=LISTWISE</code> 时，当堆叠的标度变量与分类变量嵌套在一起时，任一标度变量的缺失值都会导致该个案在所有这些变量中被排除。</p><p>作为示例，考虑以下数据集，其中 ‘x’ 是分类变量，‘y’ 和 ‘z’ 是标度变量：</p><table tabindex="0"><thead><tr><th>x</th><th>y</th><th>z</th></tr></thead><tbody><tr><td>1</td><td>.</td><td>40.00</td></tr><tr><td>1</td><td>10.00</td><td>50.00</td></tr><tr><td>1</td><td>20.00</td><td>60.00</td></tr><tr><td>1</td><td>30.00</td><td>.</td></tr></tbody></table><p>在默认缺失值处理下，‘y’ 的均值为 20（基于取值 10、20 和 30），‘z’ 的均值为 50（基于 40、50 和 60）：</p><pre><code>CTABLES /TABLE (y + z) &gt; x.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Mean</th></tr></thead><tbody><tr><td>y</td><td>x</td><td>1</td><td>20.00</td></tr><tr><td>z</td><td>x</td><td>1</td><td>50.00</td></tr></tbody></table><p>通过添加 <code>SMISSING=LISTWISE</code>，只会考虑 ‘y’ 和 ‘z’ 都非缺失的个案，因此 ‘y’ 的均值变为 15（10 和 20 的平均），‘z’ 的均值变为 55（50 和 60 的平均）：</p><pre><code>CTABLES /SMISSING LISTWISE /TABLE (y + z) &gt; x.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Mean</th></tr></thead><tbody><tr><td>y</td><td>x</td><td>1</td><td>15.00</td></tr><tr><td>z</td><td>x</td><td>1</td><td>55.00</td></tr></tbody></table><p>即使使用 <code>SMISSING=LISTWISE</code>，如果 ‘y’ 和 ‘z’ 分别与 ‘x’ 单独嵌套（而不是使用单个 ‘&gt;’ 运算符），缺失值仍会恢复为按变量逐个考虑：</p><pre><code>CTABLES /SMISSING LISTWISE /TABLE (y &gt; x) + (z &gt; x).
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Mean</th></tr></thead><tbody><tr><td>y</td><td>x</td><td>1</td><td>20.00</td></tr><tr><td>z</td><td>x</td><td>1</td><td>50.00</td></tr></tbody></table>`,15)])])}const i=d(S,[["render",o]]);export{s as __pageData,i as default};
